// 💡 Try it: Compare CPU usage - last 24h vs one week ago
timeseries from:now() - 24h, to:now(), cpu_usage_last_24h = avg(dt.host.cpu.usage)
| append
[
  timeseries from:now() - 168h - 24h, to:now() - 168h, cpu_usage_last_week = avg(dt.host.cpu.usage)
]

// 💡 Try it: Problems by status over last 24h
fetch dt.davis.problems, from:now() - 24h, to:now()
| makeTimeseries by:{status = event.status}, interval:1h, count = count()
